--
-- Name: carga_bndes_nao_automatica(bigint, text); Type: FUNCTION; Schema: etl; Owner: -
--

CREATE FUNCTION etl.carga_bndes_nao_automatica(p_execucao bigint, p_uf text) RETURNS TABLE(inseridos integer, atualizados integer, excluidos integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    CREATE TEMP TABLE _res ON COMMIT DROP AS
    WITH h AS (
        SELECT dados, md5(dados::text) AS _hash FROM stg.bndes_operacao_nao_automatica WHERE dados->>'uf' = p_uf
    ), src AS (
        SELECT dados, _hash, row_number() OVER (PARTITION BY _hash)::int AS _ocorrencia FROM h
    ), m AS (
        MERGE INTO bndes.operacao_nao_automatica t
        USING src s ON t._hash = s._hash AND t._ocorrencia = s._ocorrencia
        WHEN NOT MATCHED BY TARGET THEN
            INSERT (_hash, _ocorrencia, dados, _execucao_id) VALUES (s._hash, s._ocorrencia, s.dados, p_execucao)
        WHEN NOT MATCHED BY SOURCE AND t.uf = p_uf THEN
            DELETE
        RETURNING merge_action() AS acao, t._hash, t._ocorrencia, t.dados
    )
    SELECT * FROM m;

    SELECT p_execucao, 'bndes.operacao_nao_automatica', jsonb_build_object('_hash', _hash, '_ocorrencia', _ocorrencia), dados
    FROM _res WHERE acao = 'DELETE';

    RETURN QUERY SELECT count(*) FILTER (WHERE acao = 'INSERT')::int, 0,
                        count(*) FILTER (WHERE acao = 'DELETE')::int FROM _res;
END $$;


--
-- Name: carga_ibge_populacao(bigint, text, integer[], numeric); Type: FUNCTION; Schema: etl; Owner: -
--

CREATE FUNCTION etl.carga_ibge_populacao(p_execucao bigint, p_tipo text, p_anos integer[], p_limite_exclusao_pct numeric DEFAULT 10) RETURNS TABLE(inseridos integer, atualizados integer, excluidos integer)
    LANGUAGE plpgsql
    AS $$
DECLARE v_total_escopo bigint;
BEGIN
    SELECT count(*) INTO v_total_escopo FROM ibge.populacao WHERE tipo = p_tipo AND ano = ANY (p_anos);
    CREATE TEMP TABLE _src ON COMMIT DROP AS
    SELECT s.*, md5(row(s.populacao, s.fonte)::text) AS _hash
    FROM stg.ibge_populacao s WHERE s.tipo = p_tipo AND s.ano = ANY (p_anos);

    SELECT p_execucao, 'ibge.populacao',
           jsonb_build_object('codigo_ibge', t.codigo_ibge, 'ano', t.ano, 'tipo', t.tipo), to_jsonb(t)
    FROM ibge.populacao t JOIN _src s USING (codigo_ibge, ano, tipo)
    WHERE t._hash <> s._hash;

    CREATE TEMP TABLE _res ON COMMIT DROP AS
    WITH m AS (
        MERGE INTO ibge.populacao t
        USING _src s ON t.codigo_ibge = s.codigo_ibge AND t.ano = s.ano AND t.tipo = s.tipo
        WHEN MATCHED AND t._hash <> s._hash THEN
            UPDATE SET populacao = s.populacao, fonte = s.fonte, _hash = s._hash, _modificado_em = now(),
                       _modificado_fonte_em = s.modificado_fonte_em, _execucao_id = p_execucao
        WHEN NOT MATCHED BY TARGET THEN
            INSERT (codigo_ibge, ano, tipo, populacao, fonte, _hash, _modificado_fonte_em, _execucao_id)
            VALUES (s.codigo_ibge, s.ano, s.tipo, s.populacao, s.fonte, s._hash, s.modificado_fonte_em, p_execucao)
        WHEN NOT MATCHED BY SOURCE AND t.tipo = p_tipo AND t.ano = ANY (p_anos) THEN   -- escopo
            DELETE
        RETURNING merge_action() AS acao, t.*
    )
    SELECT * FROM m;


    -- TRAVA: fonte devolveu dados incompletos? Exclusão em massa aborta a carga inteira (rollback).
    IF (SELECT count(*) FROM _res WHERE acao = 'DELETE') > 10
       AND (SELECT count(*) FROM _res WHERE acao = 'DELETE') > v_total_escopo * p_limite_exclusao_pct / 100 THEN
        RAISE EXCEPTION 'TRAVA DE EXCLUSAO em %: % de % linhas do escopo seriam excluidas (limite % por cento). Carga abortada; verifique a fonte.',
            'ibge.populacao', (SELECT count(*) FROM _res WHERE acao = 'DELETE'), v_total_escopo, p_limite_exclusao_pct;
    END IF;

    SELECT p_execucao, 'ibge.populacao', jsonb_build_object('codigo_ibge', codigo_ibge, 'ano', ano, 'tipo', tipo),
           to_jsonb(r) - 'acao'
    FROM _res r WHERE acao = 'DELETE';

    RETURN QUERY SELECT count(*) FILTER (WHERE acao = 'INSERT')::int,
                        count(*) FILTER (WHERE acao = 'UPDATE')::int,
                        count(*) FILTER (WHERE acao = 'DELETE')::int FROM _res;
END $$;


--
-- Name: finalizar(bigint, text, text); Type: FUNCTION; Schema: etl; Owner: -
--

CREATE FUNCTION etl.finalizar(p_execucao bigint, p_status text, p_erro text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE e etl.execucao;
BEGIN
    UPDATE etl.execucao SET fim = now(), status = p_status, erro = p_erro WHERE id = p_execucao RETURNING * INTO e;
    IF p_status = 'ok' AND e.digital_novo IS NOT NULL THEN
        VALUES (e.recurso_id, e.digital_novo, now(), now())
        ON CONFLICT (recurso_id) DO UPDATE SET digital = EXCLUDED.digital, verificado_em = now(), alterado_em = now();
    END IF;
END $$;


--
-- Name: merge_tabela(bigint, regclass, regclass, text[], text[], text, numeric); Type: FUNCTION; Schema: etl; Owner: -
--

CREATE FUNCTION etl.merge_tabela(p_exec bigint, p_destino regclass, p_stg regclass, p_chaves text[], p_valores text[], p_escopo text DEFAULT 'true'::text, p_limite_exclusao_pct numeric DEFAULT 10) RETURNS TABLE(inseridos integer, atualizados integer, excluidos integer)
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_on    text := (SELECT string_agg(format('t.%1$I = s.%1$I', c), ' AND ') FROM unnest(p_chaves) c);
    v_hash  text := format('md5(row(%s)::text)', (SELECT string_agg(format('s.%I', c), ', ') FROM unnest(p_valores) c));
    v_set   text := (SELECT string_agg(format('%1$I = s.%1$I', c), ', ') FROM unnest(p_valores) c);
    v_cols  text := (SELECT string_agg(format('%I', c), ', ') FROM unnest(p_chaves || p_valores) c);
    v_vals  text := (SELECT string_agg(format('s.%I', c), ', ') FROM unnest(p_chaves || p_valores) c);
    v_chave text := (SELECT 'jsonb_build_object(' || string_agg(format('%L, t.%I', c, c), ', ') || ')' FROM unnest(p_chaves) c);
    v_total_escopo bigint;
BEGIN
    EXECUTE format('SELECT count(*) FROM %s t WHERE %s', p_destino, replace(p_escopo, '{a}', 't')) INTO v_total_escopo;
    DROP TABLE IF EXISTS _src; DROP TABLE IF EXISTS _res;
    EXECUTE format('CREATE TEMP TABLE _src ON COMMIT DROP AS SELECT s.*, %s AS _hash_novo FROM %s s WHERE %s',
                   v_hash, p_stg, replace(p_escopo, '{a}', 's'));

    EXECUTE format('INSERT INTO etl.historico (execucao_id, tabela, chave, linha_anterior)
                    SELECT %L::bigint, %L, %s, to_jsonb(t) FROM %s t JOIN _src s ON %s WHERE t._hash <> s._hash_novo',
                   p_exec, p_destino::text, v_chave, p_destino, v_on);

    EXECUTE format($m$
        CREATE TEMP TABLE _res ON COMMIT DROP AS
        WITH m AS (
            MERGE INTO %1$s t USING _src s ON %2$s
            WHEN MATCHED AND t._hash <> s._hash_novo THEN
                UPDATE SET %3$s, _hash = s._hash_novo, _modificado_em = now(),
                           _modificado_fonte_em = s.modificado_fonte_em, _execucao_id = %6$L::bigint
            WHEN NOT MATCHED BY TARGET THEN
                INSERT (%4$s, _hash, _modificado_fonte_em, _execucao_id)
                VALUES (%5$s, s._hash_novo, s.modificado_fonte_em, %6$L::bigint)
            WHEN NOT MATCHED BY SOURCE AND %7$s THEN
                DELETE
            RETURNING merge_action() AS acao, %8$s AS chave, to_jsonb(t) AS linha
        ) SELECT * FROM m$m$,
        p_destino, v_on, v_set, v_cols, v_vals, p_exec, replace(p_escopo, '{a}', 't'), v_chave);


    -- TRAVA: fonte devolveu dados incompletos? Exclusão em massa aborta a carga inteira (rollback).
    IF (SELECT count(*) FROM _res WHERE acao = 'DELETE') > 10
       AND (SELECT count(*) FROM _res WHERE acao = 'DELETE') > v_total_escopo * p_limite_exclusao_pct / 100 THEN
        RAISE EXCEPTION 'TRAVA DE EXCLUSAO em %: % de % linhas do escopo seriam excluidas (limite % por cento). Carga abortada; verifique a fonte.',
            p_destino, (SELECT count(*) FROM _res WHERE acao = 'DELETE'), v_total_escopo, p_limite_exclusao_pct;
    END IF;

    SELECT p_exec, p_destino::text, chave, linha FROM _res WHERE acao = 'DELETE';

    RETURN QUERY SELECT count(*) FILTER (WHERE acao = 'INSERT')::int,
                        count(*) FILTER (WHERE acao = 'UPDATE')::int,
                        count(*) FILTER (WHERE acao = 'DELETE')::int FROM _res;
END $_$;


