--
-- Name: recurso; Type: TABLE; Schema: etl; Owner: -
--

CREATE TABLE etl.recurso (
    id text NOT NULL,
    fonte text NOT NULL,
    modo text NOT NULL,
    metodo text NOT NULL,
    url text,
    parametros jsonb DEFAULT '{}'::jsonb NOT NULL,
    tabela_destino text,
    frequencia text DEFAULT 'diaria'::text NOT NULL,
    ativo boolean DEFAULT true NOT NULL,
    CONSTRAINT recurso_metodo_check CHECK ((metodo = ANY (ARRAY['http'::text, 'zip_crc'::text, 'ckan'::text, 'ibge_per'::text, 'siconfi'::text, 'hash_corpo'::text, 'novo_ano'::text]))),
    CONSTRAINT recurso_modo_check CHECK ((modo = ANY (ARRAY['ETL_API'::text, 'ELT_ARQUIVO'::text])))
);


--
-- Name: v_status; Type: VIEW; Schema: etl; Owner: -
--

CREATE VIEW etl.v_status AS
 SELECT r.id AS recurso,
    r.fonte,
    r.tabela_destino,
    c.verificado_em,
    c.alterado_em,
    e.id AS ultima_execucao,
    e.status,
    e.inicio,
    e.fim,
    e.escopo,
    e.inseridos,
    e.atualizados,
    e.excluidos
   FROM ((etl.recurso r
     LEFT JOIN etl.checkpoint c ON ((c.recurso_id = r.id)))
     LEFT JOIN LATERAL ( SELECT x.id,
            x.recurso_id,
            x.inicio,
            x.fim,
            x.status,
            x.escopo,
            x.digital_novo,
            x.inseridos,
            x.atualizados,
            x.excluidos,
            x.erro
           FROM etl.execucao x
          WHERE (x.recurso_id = r.id)
          ORDER BY x.id DESC
         LIMIT 1) e ON (true));


