--
-- Name: v_dicionario; Type: VIEW; Schema: meta; Owner: -
--

CREATE VIEW meta.v_dicionario AS
 SELECT (((n.nspname)::text || '.'::text) || (c.relname)::text) AS tabela,
    a.attname AS coluna,
    format_type(a.atttypid, a.atttypmod) AS tipo,
    col_description(c.oid, (a.attnum)::integer) AS descricao,
    obj_description(c.oid, 'pg_class'::name) AS descricao_tabela
   FROM ((pg_class c
     JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
     JOIN pg_attribute a ON (((a.attrelid = c.oid) AND (a.attnum > 0) AND (NOT a.attisdropped))))
  WHERE ((n.nspname = 'ibge'::name) AND (c.relkind = 'r'::"char"))
  ORDER BY (((n.nspname)::text || '.'::text) || (c.relname)::text), a.attnum;


--
-- Name: v_linha_origem; Type: VIEW; Schema: meta; Owner: -
--

CREATE VIEW meta.v_linha_origem AS
 WITH linhas AS (
         SELECT 'ibge.municipio'::text AS tabela,
            jsonb_build_object('codigo_ibge', municipio.codigo_ibge) AS chave,
            municipio._criado_em,
            municipio._modificado_em,
            municipio._modificado_fonte_em,
            municipio._execucao_id
           FROM ibge.municipio
        UNION ALL
         SELECT 'ibge.populacao'::text,
            jsonb_build_object('codigo_ibge', populacao.codigo_ibge, 'ano', populacao.ano, 'tipo', populacao.tipo) AS jsonb_build_object,
            populacao._criado_em,
            populacao._modificado_em,
            populacao._modificado_fonte_em,
            populacao._execucao_id
           FROM ibge.populacao
        UNION ALL
         SELECT 'ibge.pib_municipal'::text,
            jsonb_build_object('codigo_ibge', pib_municipal.codigo_ibge, 'ano', pib_municipal.ano) AS jsonb_build_object,
            pib_municipal._criado_em,
            pib_municipal._modificado_em,
            pib_municipal._modificado_fonte_em,
            pib_municipal._execucao_id
           FROM ibge.pib_municipal
        UNION ALL
         SELECT 'ibge.malha'::text,
            jsonb_build_object('codigo_ibge', malha.codigo_ibge) AS jsonb_build_object,
            malha._criado_em,
            malha._modificado_em,
            malha._modificado_fonte_em,
            malha._execucao_id
           FROM ibge.malha
        )
 SELECT l.tabela,
    l.chave,
    l._criado_em,
    l._modificado_em,
    l._modificado_fonte_em,
    l._execucao_id,
    e.recurso_id AS recurso,
    r.fonte,
    r.url,
    e.inicio AS carga_em,
    e.escopo AS escopo_da_carga
   FROM ((linhas l
     LEFT JOIN etl.execucao e ON ((e.id = l._execucao_id)))
     LEFT JOIN etl.recurso r ON ((r.id = e.recurso_id)));


--
-- Name: v_status_dataset; Type: VIEW; Schema: meta; Owner: -
--

CREATE VIEW meta.v_status_dataset AS
 SELECT r.tabela_destino AS tabela,
    r.id AS recurso,
    r.fonte,
    r.url,
    COALESCE(( SELECT max(p.modificacao) AS max
           FROM meta.periodo p
          WHERE (p.fonte_tabela_id = (r.parametros ->> 'fonte_tabela'::text))), ( SELECT (((f.metadados ->> 'last_modified'::text))::timestamp with time zone)::date AS date
           FROM meta.fonte_tabela f
          WHERE (f.id = (r.parametros ->> 'fonte_tabela'::text)))) AS ultima_modificacao_fonte,
    s.alterado_em AS ultima_alteracao_banco,
    s.verificado_em AS ultima_verificacao,
    s.status AS status_ultima_execucao,
    s.inseridos,
    s.atualizados,
    s.excluidos,
    ( SELECT min(c.data_divulgacao) AS min
           FROM meta.calendario c
          WHERE ((c.produto_id = ((r.parametros ->> 'produto_id'::text))::integer) AND (c.data_divulgacao > now()))) AS proxima_divulgacao,
    ( SELECT max(c.data_divulgacao) AS max
           FROM meta.calendario c
          WHERE ((c.produto_id = ((r.parametros ->> 'produto_id'::text))::integer) AND (c.data_divulgacao <= now()))) AS ultima_divulgacao
   FROM (etl.recurso r
     JOIN etl.v_status s ON ((s.recurso = r.id)))
  WHERE (r.tabela_destino IS NOT NULL);


